package pool

import (
	"context"
	"sync"
)

// Job is one unit of work. Run performs the work and must honour ctx.
type Job struct {
	ID  int
	Run func(ctx context.Context) error
}

// Result carries the outcome of a Job.
type Result struct {
	ID  int
	Err error
}

// Process runs at most `workers` handlers over jobs.
func Process(ctx context.Context, jobs <-chan Job, workers int) <-chan Result {
	out := make(chan Result)
	if workers <= 0 {
		close(out)
		return out
	}

	var wg sync.WaitGroup
	wg.Add(workers)
	for i := 0; i < workers; i++ {
		go func() {
			defer wg.Done()
			for {
				if ctx.Err() != nil {
					return
				}
				select {
				case <-ctx.Done():
					return
				case job, ok := <-jobs:
					if !ok {
						return
					}
					err := job.Run(ctx)
					select {
					case out <- Result{ID: job.ID, Err: err}:
					case <-ctx.Done():
						return
					}
				}
			}
		}()
	}

	go func() {
		wg.Wait()
		close(out)
	}()

	return out
}

