  renderer.render(scene, camera);
  let energy = 0;
  for (let i = 1; i < N - 1; i++) {
    const du = u[i] - prev[i];
    const dr = u[i + 1] - u[i];
    energy += 0.5 * du * du + 0.5 * C2 * dr * dr;
